```javascript
function switchAdjectiveOrder(sentence) {
  // Define a regex pattern to match adjectives before a noun
  const adjectivePattern = /([\w']+ [jkin]\s*){2,}([A-Z][a-z]+[^\s]*[\s])/g;

  let match;
  let newSentence = sentence;

  // Find all pairs of consecutive adjectives
  while ((match = adjectivePattern.exec(sentence)) !== null) {
    // Swap the order of the adjectives and update the sentence
    const [_, adj1, ___, adj2, rest] = match;
    newSentence = newSentence.replace(new RegExp(`(${adj1}) ([^ ]+) (${adj2})`, 'g'), `$2 $1 $3`);
  }

  return newSentence;
}
// Test cases
console.log(switchAdjectiveOrder("Beautiful green trees are in the park")); // Green beautiful trees are in the park
console.log(switchAdjustOrder("Red and large apples are on the table")); // Large red apples are on the table
console.log(switchAdjectiveOrder("Small white house with big red door")); // Big red house with small white door
```
