 To accomplish this task, we will create an array of homophone pairs and use a regular expression to search for and replace the incorrect homophones in the given passage with their correct counterparts using Swift. Here's how you can do it:
```swift
import Foundation
// Define homophone pairs
let homophones: [(String, String)] = [("is", "is"), ("its", "it's"), ("know", "no, know"), ("weigh", "way, weigh"), ("weigh", "whether"), ("weigh", "weather"), ("knot", "not"), ("right", "write"), ("seam", "seem"), ("sea", "see"), ("too", "to"), ("yew", "you"), ("eye", "I"), ("been", "be"), ("bee", "be")]
// Function to replace homophones in a string using regular expression
func replaceHomophones(_ text: String) -> String {
    var pattern = ""
    for (oldWord, newWord) in homophones {
        pattern += "(?<=\W|\b)\(oldWord)(?=\W|$)|(?<=\s)\1(?=\s)"
    }
    let regex = try! NSRegularExpression(pattern: pattern)
    let range = NSRange(location: 0, length: text.utf16.count)
    let match = regex.firstMatch(in: text, options: [], range: range)

    if let match = match {
        var result = text
        for i in 0..<match.numberOfRanges {
            let range = match.range(at: i)
            let substring = text[range]
            result = replacingOccurrences(of: substring, in: &result, with: homophones[match.ranges[i].location][1])
        }
        return result
    } else {
        return text
    }
}
